/* =================================================================== */
/*                                                                     */
/*  Documentation:                                                     */
/*                                                                     */
/*  Utility . . . : RTVUSRAUT                                          */
/*  Object  . . . : A_INSTALL  (PGM)                                   */
/*  Source member : A_INSTALL                                          */
/*  Source type . : CLLE                                               */
/*  Description   : RTVUSRAUT - Installer                              */
/*  Author  . . . : Thomas Raddatz   <thomas.raddatz@tools400.de>      */
/*                                                                     */
/* =================================================================== */
/*                                                                     */
/*  This software is free software, you can redistribute it and/or     */
/*  modify it under the terms of the GNU General Public License (GPL)  */
/*  as published by the Free Software Foundation.                      */
/*                                                                     */
/*  See GNU General Public License for details.                        */
/*          http://www.opensource.org                                  */
/*          http://www.opensource.org/licenses/gpl-license.html        */
/*                                                                     */
/* =================================================================== */
/*  History:                                                           */
/*                                                                     */
/*  Datum       Name          Änderung                                 */
/*  ----------  ------------  ---------------------------------------  */
/*                                                                     */
/* =================================================================== */
/*   >>PRE-COMPILER<<                                                  */
/*     >>CRTCMD<<    CRTBNDCL  PGM(QTEMP/&OB) +                        */
/*                             SRCFILE(&SL/&SF) SRCMBR(&SM);           */
/*     >>IMPORTANT<<                                                   */
/*       >>PARM<<    OPTION(*EVENTF);                                  */
/*     >>END-IMPORTANT<<                                               */
/*     >>EXECUTE<<                                                     */
/*     >>CMD<<       CALL   PGM(QTEMP/A_INSTALL) +                     */
/*                          PARM('*CURRENT' '&SF' '&LI');              */
/*     >>CMD<<       DLTPGM PGM(QTEMP/A_INSTALL);                      */
/*   >>END-PRE-COMPILER<<                                              */
/* =================================================================== */
        PGM        PARM(&TGTRLS &SRCFILE &TOLIB)

        DCL        VAR(&TGTRLS   ) TYPE(*CHAR) LEN(10)
        DCL        VAR(&SRCFILE  ) TYPE(*CHAR) LEN(10)
        DCL        VAR(&TOLIB    ) TYPE(*CHAR) LEN(10)

        DCL        VAR(&SRCLIB   ) TYPE(*CHAR) LEN(10)

        DCL        VAR(&PNLGRP   ) TYPE(*CHAR) LEN(10)
        DCL        VAR(&DSPF     ) TYPE(*CHAR) LEN(10)
        DCL        VAR(&CMD      ) TYPE(*CHAR) LEN(10)

        CHGVAR     VAR(&SRCLIB) VALUE(&TOLIB   )

        CHGVAR     VAR(&PNLGRP ) VALUE('RTVUSRAUTP')
        CHGVAR     VAR(&CMD    ) VALUE('RTVUSRAUT')

/* ---------------------------------- */
/*  Delete old objects                */
/* ---------------------------------- */
        DLTCMD     CMD(&TOLIB/RTVUSRAUT)
        MONMSG     MSGID(CPF2105)

        DLTPNLGRP  PNLGRP(&TOLIB/RTVUSRAUTP)
        MONMSG     MSGID(CPF2105)

        DLTMOD     MODULE(&TOLIB/RTVUSRA1)
        MONMSG     MSGID(CPF2105)

        DLTPGM     PGM(&TOLIB/RTVUSRAUT)
        MONMSG     MSGID(CPF2105)

/* -------------------------------- */
/*  Create modules                  */
/* -------------------------------- */
        CRTRPGMOD  MODULE(&TOLIB/RTVUSRA1) +
                     SRCFILE(&SRCLIB/&SRCFILE) +
                     SRCMBR(*MODULE) +
                     DBGVIEW(*LIST) TRUNCNBR(*NO) +
                     TGTRLS(&TGTRLS)
        DLTSPLF    FILE(RTVUSRA1) JOB(*) SPLNBR(*LAST)
        MONMSG     MSGID(CPF0000)

/* -------------------------------- */
/*  Create programs                 */
/* -------------------------------- */
        CRTPGM     PGM(&TOLIB/RTVUSRAUT) +
                   MODULE(&TOLIB/RTVUSRA1) +
                     ACTGRP(*NEW) +
                     DETAIL(*BASIC) +
                     TGTRLS(&TGTRLS)
        DLTSPLF    FILE(RTVUSRAUT) JOB(*) SPLNBR(*LAST)
        MONMSG     MSGID(CPF0000)

/* -------------------------------- */
/*  Create panel groups             */
/* -------------------------------- */
        CRTPNLGRP  PNLGRP(&TOLIB/RTVUSRAUTP) +
                     SRCFILE(&SRCLIB/&SRCFILE) +
                     SRCMBR(&PNLGRP)
        DLTSPLF    FILE(RTVUSRAUTP) JOB(*) SPLNBR(*LAST)
        MONMSG     MSGID(CPF0000)

/* -------------------------------- */
/*  Create commands                 */
/* -------------------------------- */
        CRTCMD     CMD(&TOLIB/RTVUSRAUT) PGM(&TOLIB/RTVUSRAUT) +
                     SRCFILE(&SRCLIB/&SRCFILE) +
                     SRCMBR(&CMD) +
                     HLPPNLGRP(&TOLIB/RTVUSRAUTP) HLPID(RTVUSRAUT) +
                     ALLOW(*BPGM *IPGM *BREXX *IREXX *BMOD *IMOD)
        DLTSPLF    FILE(&CMD     ) JOB(*) SPLNBR(*LAST)
        MONMSG     MSGID(CPF0000)

/* -------------------------------- */
/*  Delete obsolete objects         */
/* -------------------------------- */
        DLTMOD     MODULE(&TOLIB/RTVUSRA1)

        ENDPGM

**free
ctl-opt debug option(*srcstmt: *nodebugio);
/if not defined(NO_DECEDIT)
ctl-opt decedit('0,');
/endif
ctl-opt datedit(*DMY.);
ctl-opt datfmt(*iso);
ctl-opt timfmt(*iso);
ctl-opt expropts(*resdecpos);
ctl-opt extbinint(*yes);
/copy qrtvusraut,copyright

**free

//  Retrieve User Authority to Object (QSYRUSRA) API
dcl-pr QSYRUSRA extpgm('QSYRUSRA');
  o_rcvVar    char(65535) options(*varsize);
  i_rcvVarLen int(10) const;
  i_format    char(8) const;
  i_usrPrf    char(10) const;
  i_qObj      char(20) const;
  i_objType   char(10) const;
  io_errCode  char(65535) options(*varsize);
end-pr;

dcl-ds usra0100_t qualified template;
  bytRet        int(10);
  bytAvl        int(10);
  objAut        char(10);
  autLstMgmt    char(1);
  objOper       char(1);
  objMgmt       char(1);
  objExist      char(1);
  dataRead      char(1);
  dataAdd       char(1);
  dataUpdate    char(1);
  dataDelete    char(1);
  autLst        char(10);
  autSrc        char(2);
  someAdpAut    char(1);
  adpAut        char(10);
  adpAutLstMgmt char(1);
  adpObjOper    char(1);
  adpObjMgmt    char(1);
  adpObjExist   char(1);
  adpObjRead    char(1);
  adpObjAdd     char(1);
  adpObjUpdate  char(1);
  adpObjDelete  char(1);
  adpObjExec    char(1);
  reserved_1    char(10);
  adpObjAlter   char(1);
  adpObjRef     char(1);
  reserved_2    char(10);
  dataExec      char(1);
  reserved_3    char(10);
  objAlter      char(1);
  objRef        char(1);
  aspDevNmeLib  char(10);
  aspDevNmeObj  char(10);
  reserved_4    char(3);
  ofsGrpInf     int(10);
  numGrpE       int(10);
end-ds;
//  char(*)     Group information table repeated for each of the
//              user's groups

